def two_sum(nums, target):
    seen = {}  # value -> index
    for i, n in enumerate(nums):
        if target - n in seen:
            return [seen[target - n], i]
        seen[n] = i

print(two_sum([2, 7, 11, 15], 9))  # [0, 1]

from collections import defaultdict

def group_anagrams(words):
    groups = defaultdict(list)  # sorted letters -> words
    for w in words:
        groups["".join(sorted(w))].append(w)
    return list(groups.values())

print(group_anagrams(["eat", "tea", "tan", "nat"]))

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2  # no overflow in other languages
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def is_palindrome(s):
    s = [c.lower() for c in s if c.isalnum()]
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left, right = left + 1, right - 1
    return True

print(is_palindrome("A man, a plan, a canal: Panama"))  # True

class Node:
    def __init__(self, val, next=None):
        self.val, self.next = val, next

def reverse(head):
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def next_greater(nums):
    result = [-1] * len(nums)
    stack = []  # indexes still waiting for a bigger number
    for i, n in enumerate(nums):
        while stack and nums[stack[-1]] < n:
            result[stack.pop()] = n
        stack.append(i)
    return result

print(next_greater([2, 1, 5, 3]))  # [5, 5, -1, -1]

from collections import deque

def bfs(graph, start):
    seen, queue = {start}, deque([start])
    while queue:
        node = queue.popleft()  # O(1), list.pop(0) is O(n)
        print(node)
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)

from collections import Counter

def is_anagram(a, b):
    return Counter(a) == Counter(b)

print(is_anagram("listen", "silent"))  # True
print(Counter("banana").most_common(1))  # [('a', 3)]

from functools import lru_cache

@lru_cache(maxsize=None)
def climb(n):
    # ways to climb n stairs taking 1 or 2 steps
    if n <= 2:
        return n
    return climb(n - 1) + climb(n - 2)

print(climb(40))  # 165580141, instant

parent = list(range(5))  # each node starts as its own root
def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])  # point straight to the root
    return parent[x]

def union(a, b):
    parent[find(a)] = find(b)

union(0, 1); union(1, 2)
print(find(0) == find(2))  # True
